function op(action,body){if(action==='start'&&ctx.data.run.kind!=='review'){ctx.attemptToken=ctx.attemptToken||root.crypto.randomUUID();body={attemptToken:ctx.attemptToken};ctx.checkpointVersion=0;ctx.submitKey=null;ctx.checkpointError=false;ctx.checkpointPending=null;ctx.checkpointQueue=Promise.resolve();}var runId=ctx.data.run.id,box=action==='answer'&&ctx.data.run.status==='active'&&host.querySelector('#feImage'),frame=box?{runId:runId,position:ctx.data.run.currentPosition,height:box.getBoundingClientRect().height}:null;return request(function(){return call('POST',runPath(ctx.data.run)+'/'+action,body);},function(d){accept(d);},function(){load(runId);},action==='start'?'#feJump':action==='submit'?'#feResult':null);}
function image(item,box,only,done){if(!only&&ctx.data&&ctx.data.run.kind==='review'&&root.HanqLearningReader){var original=root.HanqLearningReader.history(item,box);if(original)box=original;}var token=ctx.seq,owner=ctx.owner;var paths=(only?[only]:(item.common?[item.common.image,item.image]:[item.image])).filter(function(p,i,a){return a.indexOf(p)===i;}),left=paths.length;function settle(){if(done&&!--left&&valid()&&box.isConnected)done();}paths.forEach(function(path,index){var figure=root.document.createElement('figure'),status=root.document.createElement('p');status.setAttribute('role','status');status.textContent='원본 문제를 불러오는 중이에요…';figure.appendChild(status);box.appendChild(figure);(ctx.cache[path]?Promise.resolve(ctx.cache[path]):api.cbtImage(path,{attemptToken:ctx.attemptToken})).then(function(blob){if(!valid()||ctx.seq!==token||current()!==owner||!figure.isConnected)return;ctx.cache[path]=blob;var u=root.URL.createObjectURL(blob);ctx.urls.push(u);figure.replaceChildren();if(item.common&&path===item.common.image){var cap=root.document.createElement('figcaption');cap.textContent='공통 자료 '+item.common.questionNumbers.join('·')+'번';figure.appendChild(cap);}var a=root.document.createElement('a');a.href=u;a.target='_blank';a.rel='noopener';a.setAttribute('aria-label',item.number+'번 원본 크게 보기');var img=root.document.createElement('img');img.className='mock-image';img.src=u;img.alt=(item.common&&path===item.common.image?'공통 자료':item.exam+'회 '+item.number+'번 원본 문제·보기');a.appendChild(img);var caption=root.document.createElement('span');caption.className='fe-image-open';caption.textContent='원본 크게 보기';a.appendChild(caption);var pane=root.document.createElement('div');pane.className='fe-image-pane';pane.appendChild(a);var zoom=root.document.createElement('button');zoom.type='button';zoom.className='tool-btn fe-image-zoom';zoom.textContent='확대 보기';zoom.disabled=true;function applyZoom(){var on=ctx.imageZoom[path]===true;img.style.width=on?Math.max(img.naturalWidth,Math.round(pane.clientWidth*1.5))+'px':'100%';img.style.maxWidth=on?'none':'100%';zoom.textContent=on?'화면에 맞추기':'확대 보기';zoom.setAttribute('aria-pressed',String(on));}zoom.onclick=function(){ctx.imageZoom[path]=!ctx.imageZoom[path];applyZoom();};if(ctx.data&&ctx.data.run.kind==='review')figure.appendChild(zoom);figure.appendChild(pane);var fin=function(){if(fin.called)return;fin.called=true;if(img.naturalWidth>0){zoom.disabled=false;applyZoom();}settle();};function decodeFail(){if(!valid()||ctx.seq!==token||current()!==owner||!figure.isConnected)return;figure.replaceChildren(status);status.setAttribute('role','alert');status.textContent='원본 문제 이미지를 표시하지 못했어요. 다시 불러와 주세요.';var b=root.document.createElement('button');b.type='button';b.className='tool-btn';b.textContent='이미지 다시 확인';b.onclick=function(){figure.remove();image(item,box,path);};figure.appendChild(b);fin();}if(img.decode)img.decode().then(fin,decodeFail);else{img.onload=fin;img.onerror=decodeFail;}},function(e){if(!valid()||ctx.seq!==token||current()!==owner||!figure.isConnected)return;status.setAttribute('role','alert');status.textContent='원본 이미지를 불러오지 못했어요. 공개 주소로 대신 열지 않아요.';var retry=root.document.createElement('button');retry.className='tool-btn';retry.type='button';retry.textContent='이미지 다시 확인';retry.onclick=function(){figure.remove();image(item,box,path);};figure.appendChild(retry);settle();});});}
/* 시대 표는 ERA 화이트리스트만 행·링크로 보여 준다. 예전 결과에 남은 비지원 시대 버킷(예: comprehensive)은 미확인 문항 수에 더한다 */
function eraView(stats){var e=stats&&stats.eras||{},rows=[],n=Number(e.excluded&&e.excluded.count)||0;(Array.isArray(e.buckets)?e.buckets:[]).forEach(function(r){if(r&&Object.prototype.hasOwnProperty.call(ERA,r.key))rows.push(r);else n+=Number(r&&r.total)||0;});return{rows:rows,excluded:n};}
function excludedNote(stats){var n=eraView(stats).excluded;return n>0?'<p>통사·시대 미확인 '+n+'문항은 특정 시대 통계에 넣지 않았어요.</p>':'';}
function statsHtml(stats,era){var rows=era?eraView(stats).rows:(stats&&stats.parts&&stats.parts.buckets)||[];return'<table class="fe-stats"><thead><tr><th scope="col">'+(era?'시대':'파트')+'</th><th scope="col">오답 / 출제</th><th scope="col">오답률</th><th scope="col">학습</th></tr></thead><tbody>'+rows.map(function(r){var pct=r.wrongRate==null?null:Math.round(r.wrongRate*1000)/10,label=era?ERA[r.key]:r.key,link=era?r.key:null;return'<tr><th scope="row">'+esc(label)+'</th><td>'+r.wrong+' / '+r.total+'</td><td>'+(pct==null?'미평가':pct+'%<meter min="0" max="100" value="'+pct+'" aria-label="'+esc(label)+' 오답률 '+pct+'퍼센트">'+pct+'%</meter>')+'</td><td>'+(link?'<button type="button" class="tool-btn fe-learn" data-era="'+esc(link)+'">학습</button><button type="button" class="tool-btn fe-learn" data-era="'+esc(link)+'" data-review="1">복습</button>':'–')+'</td></tr>';}).join('')+'</tbody></table>';}
/* 서버가 저장한 최종 결과(score/maxScore/correct/total/growthReward)를 모양이 맞을 때만 짧게 보여 준다(점수를 짐작하지 않음) */function cbtScore(x){var n=function(v,a,b){return Number.isSafeInteger(v)&&v>=a&&v<=b;};if(!x||typeof x!=='object'||x.maxScore!==100||x.total!==50||!n(x.score,0,100)||!n(x.correct,0,50))return '';return ' '+x.score+'/100점 · '+x.correct+'/50문항 정답'+(Number.isSafeInteger(x.growthReward)?' → 성장점수 '+(x.growthReward>0?'+':'')+x.growthReward+'점':'');}function analysisHtml(d){if(d.run.kind==='review'){var R=root.HanqCbtResultAnalysis,a=R?R.analyze(d.items):null;return '<h3>문항별 결과 · 시대</h3><div class="fe-question-grid">'+d.items.map(function(q){var row=a&&a.rows.find(function(x){return x.position===q.position;});return '<button type="button" class="fe-question fe-question--'+q.review.status+'" data-review-position="'+q.position+'"><b>'+q.number+'번 - '+esc(row?row.eraLabel:'분류 확인 필요')+'</b></button>';}).join('')+'</div>';}var A=root.HanqCbtResultAnalysis;if(!A)return '<h3>취약 시대</h3>'+statsHtml(d.run.result.stats,true)+'<h3>취약 파트</h3>'+statsHtml(d.run.result.stats,false)+excludedNote(d.run.result.stats);var a=A.analyze(d.items);return '<section class="fe-analysis"><h3>문항별 결과 · 시대</h3><div class="fe-question-grid">'+a.rows.map(function(q){return '<button type="button" class="fe-question fe-question--'+q.status+'" data-review-position="'+q.position+'" aria-label="'+q.number+'번 · '+(q.correct?'정답':q.unanswered?'미응답':'오답')+' · '+esc(q.eraLabel)+' · '+esc(q.part)+(starred(q.position)?' · 별표':'')+'" title="'+esc(q.eraLabel)+' · '+esc(q.part)+'"><b>'+q.number+'번 - '+esc(q.eraLabel)+'</b></button>';}).join('')+'</div>'+weaknessBars(a)+(!a.verified?'<p>일부 문항의 세부 파트는 검수가 필요한 초기 분류입니다.</p>':'')+(d.run.round===79?'<p>50번은 여러 시대를 비교하는 복합 문항으로, 해설의 정답 핵심을 기준으로 시대·파트를 집계합니다.</p>':'')+'</section>';}
function historyGrowthHtml(s){if(s.growthPolicy==='round-first-score-bands-v1'&&Number.isInteger(s.growthReward))return '<p class="fe-growth">성장점수 <b>'+(s.growthReward>0?'+':'')+s.growthReward+'점</b> · '+(s.rewardEligible?'이 회차 최초 완료 보상':'이미 완료한 회차 · 재풀이는 XP 변동 없음')+'<br><small>계정별·회차별 최초 1회 · 80~100점 +10 · 70~79점 +5 · 60~69점 +3 · 60점 미만 −10 · 보유 점수까지만 차감</small></p>';if(s.growthPolicy==='per-question-original-points'&&Number.isInteger(s.growthReward))return '<p class="fe-growth">성장점수 <b>'+(s.growthReward>0?'+':'')+s.growthReward+'점</b> · 정답 +원본 배점 / 오답 −원본 배점 / 미응답 0 · 보유 점수까지만 차감</p>';return (Number.isInteger(s.growthReward)?'<p class="fe-growth">성장점수 <b>'+(s.growthReward>0?'+':'')+s.growthReward+'점</b>'+(cbtScore(s)?' — 최종 점수 '+s.score+'/100점('+s.correct+'/50문항 정답)'+(s.score<60?'이 60점 미만이라 차감':' 구간 보상'):'')+' · 최종 점수 구간 보상(문항별 보상은 없어요) · 보유 점수까지만 차감해요<br><small>기준: 60점 미만 −100 · 60~69점 +50 · 70~79점 +100 · 80~89점 +150 · 90점 이상 +200</small></p>':'');}
function result(d){var r=d.run,s=r.result;paint('<h2 id="feResult" tabindex="-1">제'+r.round+'회 '+(r.kind==='review'?'오답·별표 재풀이 결과':'결과')+'</h2>'+(r.kind==='review'?'<p class="result-score">정답 '+s.correct+' · 오답 '+s.wrong+' · 미응답 '+s.unanswered+'</p><p>'+s.total+'문항 부분 재풀이 · 전체 시험 점수와 별도로 저장했어요. 미응답은 누적 오답에 더하지 않아요.</p>':'<p class="result-score">'+s.score+' / '+s.maxScore+'점</p><p>'+(s.grade?s.grade+'급 기준':'인증 기준 미달')+' · 맞힘 '+s.correct+' · 오답 '+((Number.isInteger(s.total)?s.total:d.items.length)-s.correct)+' (미응답 포함) · 미응답 '+s.unanswered+'</p><p>원래 배점으로 계산한 개인 연습 결과예요.</p>')+historyGrowthHtml(s)+'<button type="button" class="tool-btn" id="feWrongNotes">나만의 오답노트</button>'+analysisHtml(d)+starredResults(d)+'<p id="feStarStatus" role="status" aria-live="polite"></p><h3>정답·해설</h3><ol class="fe-reviews">'+d.items.map(function(q){var v=q.review;return'<li class="fe-review fe-review--'+v.status+'"><details data-position="'+q.position+'"><summary>'+q.number+'번 · '+(v.status==='correct'?'정답':v.status==='wrong'?'오답':'미응답')+' · '+v.earned+'/'+q.points+'점 '+starBadge(q.position)+'</summary><button type="button" class="tool-btn" data-toggle-star="'+q.position+'" aria-pressed="'+starred(q.position)+'"'+(ctx.starPending?' disabled':'')+'>'+ (starred(q.position)?'★':'☆')+' '+q.number+'번 별표</button><div class="fe-review-original"></div>'+answerCompare(q)+'<div class="fe-review-body"></div></details></li>';}).join('')+'</ol><button type="button" class="tool-btn" id="feList">회차 목록</button>');host.querySelectorAll('[data-toggle-star]').forEach(function(b){b.onclick=function(){localStar(Number(b.dataset.toggleStar));};});starStatus();bind('#feWrongNotes',function(){stop();o.onNotes();});host.querySelectorAll('[data-review-position]').forEach(function(b){b.onclick=function(){var dt=host.querySelector('.fe-reviews details[data-position="'+b.dataset.reviewPosition+'"]');if(dt){host.querySelectorAll('.fe-question-grid [aria-current]').forEach(function(x){x.removeAttribute('aria-current');});var target=host.querySelector('.fe-question-grid [data-review-position="'+b.dataset.reviewPosition+'"]');if(target)target.setAttribute('aria-current','true');dt.open=true;dt.querySelector('summary').focus();dt.scrollIntoView({block:'start'});}};});/* 최종 점수 보상이 기록된 결과면 내 총점을 한 번 다시 받는다(계정·로그인이 같을 때만 — api.refreshProfile/me가 지킴) */if(Number.isInteger(s.growthReward)&&api.refreshProfile&&!ctx.refreshed[r.id]&&current()===ctx.owner){ctx.refreshed[r.id]=1;api.refreshProfile();}bind('#feList',function(){o.onRoute(null);list();});host.querySelectorAll('.fe-learn').forEach(function(b){b.onclick=function(){stop();o.onLearn(b.dataset.era,!!b.dataset.review);};});host.querySelectorAll('.fe-reviews details').forEach(function(dt){dt.ontoggle=function(){if(!valid()||!dt.isConnected||!dt.open||dt.dataset.filled)return;dt.dataset.filled='1';var q=d.items[Number(dt.dataset.position)],v=q.review,box=dt.querySelector('.fe-review-body');box.innerHTML=(root.HanqCbtExplanations?root.HanqCbtExplanations.render(q,o.review,d.run.status):o.review?o.review.render(v.item,q.selectedOptionId||null):'<ol>'+v.options.map(function(x){return'<li>'+esc(Array.isArray(x.explanation)?x.explanation.join(' '):x.explanation)+'</li>';}).join('')+'</ol>');image(q,dt.querySelector('.fe-review-original'));};});}
/* Server stars are owner/question/version scoped; exact legacy device snapshots remain untouched. */
function starsKey(run){return 'hanq:cbt-stars:v1:'+ctx.owner+':'+run.id;}
function hydrateStars(d){var sig=signature(d),old=ctx.stars,server=validStarResponse(d,d.serverStars)?d.serverStars:null,saved=storedStars(d,starsKey(d.run)),pending=storedStars(d,pendingStarsKey(d))||d.pendingStarChanges;
 var flags=server?server.flags.slice():old&&old.owner===ctx.owner&&old.run===d.run.id&&old.signature===sig?old.flags.slice():saved&&Array.isArray(saved.flags)&&saved.flags.length===d.items.length?saved.flags.map(function(x){return x===true;}):d.items.map(function(){return false;});
 if(pending&&pending.changes)Object.keys(pending.changes).forEach(function(p){if(/^\d+$/.test(p)&&Number(p)<flags.length&&typeof pending.changes[p]==='boolean')flags[Number(p)]=pending.changes[p];});
 ctx.stars={owner:ctx.owner,run:d.run.id,signature:sig,flags:flags};ctx.starSyncError=!!d.starSyncError;ctx.starStorageError=false;
}
function starred(position){return !!(ctx.stars&&ctx.stars.flags[position]);}
function starCount(){return ctx.stars?ctx.stars.flags.filter(function(x){return x;}).length:0;}
function jumpLabel(q){return q.number+'번'+(starred(q.position)?' · ★ 별표':'')+(q.selectedOptionId?' · 답함':'');}
function starBadge(position){return starred(position)?'<span class="fe-star-label">★ 별표</span>':'';}
function starStatus(){var e=host.querySelector('#feStarStatus');if(e)e.textContent=ctx.starPending?'별표를 계정에 저장 중이에요…':ctx.starSyncError?'별표를 서버에 저장하거나 확인하지 못했어요. 표시를 보관했으니 다시 확인해 주세요.':ctx.starStorageError?'별표 임시저장에 실패했어요. 화면을 유지하고 다시 확인해 주세요.':'별표 '+starCount()+'문항 · 본인 계정에 저장돼요.';
 var retry=host.querySelector('#feStarRetry');if((ctx.starSyncError||ctx.starStorageError)&&e&&!retry){retry=root.document.createElement('button');retry.type='button';retry.className='tool-btn';retry.id='feStarRetry';retry.textContent='별표 저장 다시 확인';e.after(retry);retry.onclick=function(){if(ctx.starPending)return;ctx.starPending=true;starStatus();syncStars(ctx.data).then(function(){hydrateStars(ctx.data);ctx.starPending=false;refreshStarDom();},function(){ctx.starPending=false;ctx.starSyncError=true;starStatus();});};}else if(retry&&!ctx.starSyncError&&!ctx.starStorageError)retry.remove();
}
function refreshStarDom(){var b=host.querySelector('#feStar'),pos=ctx.data.run.currentPosition;if(b){b.disabled=ctx.starPending;b.setAttribute('aria-pressed',String(starred(pos)));b.innerHTML='<span aria-hidden="true">'+(starred(pos)?'★':'☆')+'</span> 별표';}var select=host.querySelector('#feJump');if(select)ctx.data.items.forEach(function(q){select.options[q.position].textContent=jumpLabel(q);});if(ctx.data.run.status==='final')result(ctx.data);else starStatus();}
function localStar(position){if(!valid()||ctx.pending||ctx.starPending||!ctx.stars||current()!==ctx.owner||!ctx.data.items[position])return;
 var d=ctx.data,owner=ctx.owner,sig=signature(d),saved=storedStars(d,pendingStarsKey(d))||{owner:owner,run:d.run.id,signature:sig,changes:{}};if(!saved.changes||typeof saved.changes!=='object')saved.changes={};
 var value=!starred(position);saved.changes[position]=value;d.pendingStarChanges=saved;ctx.stars.flags[position]=value;ctx.starPending=true;ctx.starSyncError=false;
 try{root.localStorage.setItem(pendingStarsKey(d),JSON.stringify(saved));ctx.starStorageError=false;}catch(e){ctx.starStorageError=true;}refreshStarDom();
 raw('POST',runPath(d.run)+'/stars',{signature:sig,position:position,starred:value}).then(function(state){if(!valid()||current()!==owner||ctx.data!==d)return;if(!validStarResponse(d,state))throw Error('invalid stars');delete saved.changes[position];try{if(Object.keys(saved.changes).length)root.localStorage.setItem(pendingStarsKey(d),JSON.stringify(saved));else root.localStorage.removeItem(pendingStarsKey(d));}catch(e){}d.serverStars=state;d.starSyncError=false;d.pendingStarChanges=Object.keys(saved.changes).length?saved:null;ctx.starStorageError=false;ctx.stars.flags=state.flags.slice();ctx.starPending=false;ctx.starSyncError=false;refreshStarDom();}).catch(function(){if(!valid()||current()!==owner||ctx.data!==d)return;ctx.starPending=false;ctx.starSyncError=true;refreshStarDom();});
}
function starredResults(d){var marked=d.items.filter(function(q){return starred(q.position);});if(!marked.length)return '';
 return '<section class="fe-starred-review" aria-labelledby="feStarredTitle"><h3 id="feStarredTitle">별표 문제 '+marked.length+'문항</h3><p>'+(ctx.starSyncError?'별표 서버 저장을 다시 확인해 주세요.':'본인 계정에 보관한 표시예요.')+'</p><nav aria-label="별표 문제 해설 바로 가기">'+marked.map(function(q){return '<button type="button" class="tool-btn" data-review-position="'+q.position+'">★ '+q.number+'번 · '+(q.review.status==='correct'?'정답':q.review.status==='wrong'?'오답':'미응답')+'</button>';}).join('')+'</nav></section>';
}
// Device drafts contain only the owner's exact run/question versions and option ids.
function draftKey(r){return 'hanq:cbt-draft:v1:'+ctx.owner+':'+r.id;}
function signature(d){return JSON.stringify(d.items.map(function(q){return[q.questionId,q.version,q.options.map(function(x){return x.id;})];}));}
function persist(){if(ctx.data&&ctx.data.run.kind!=='review'){checkpointStatus();return;}if(!ctx.draft||!ctx.data||ctx.owner!==current())return;try{root.localStorage.setItem(draftKey(ctx.data.run),JSON.stringify(ctx.draft));ctx.storageError=false;}catch(e){ctx.storageError=true;}var warning=host.querySelector('#feDraftStatus');if(warning)warning.textContent=ctx.storageError?'기기 임시저장에 실패했어요. 이 화면을 유지하고 제출해 주세요.':'답안은 이 기기에 임시 보관되고, 일시정지 또는 제출할 때 서버에 저장됩니다.';}
